/**
 * Proactive insights: what the student should know today, without asking.
 *
 * Computed by rules over real state and live rates, not generated by a model,
 * so a briefing can never invent a balance or a deadline. Each insight carries an
 * action the assistant can take on the student's behalf.
 */
import { and, eq, isNull } from 'drizzle-orm';
import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import { obligations, rateAlerts } from '../db/schema';
import { formatAmount, parseRate, sourcePrincipalFor, type Currency } from '../domain/money';
import { fxHistory } from '../rates/history';
import { liveMidRate } from '../rates/live';
import { listProposals, pocketsFor } from './wallet';
import type { ResolvedSession } from './workspace';

type Db = NodePgDatabase<Record<string, never>>;

export interface Insight {
  readonly id: string;
  readonly severity: 'urgent' | 'attention' | 'info' | 'good';
  readonly title: string;
  readonly body: string;
  /** A message to send to the assistant, which then does the work. */
  readonly ask?: string;
  readonly askLabel?: string;
}

export async function insightsFor(
  db: Db,
  session: ResolvedSession,
  profile: { home: Currency; study: Currency },
): Promise<Insight[]> {
  const out: Insight[] = [];
  const now = Date.now();
  const pockets = await pocketsFor(db, session.id);
  const bal = (c: string) => pockets.find((p) => p.currency === c);

  // 1. Bills: how soon, and can they be covered.
  const bills = (await db.select().from(obligations).where(eq(obligations.sessionId, session.id)))
    .filter((b) => !b.paidAt)
    .sort((a, b) => a.deadlineAt.getTime() - b.deadlineAt.getTime());
  for (const b of bills.slice(0, 2)) {
    const cur = b.currency as Currency;
    const days = Math.floor((b.deadlineAt.getTime() - now) / 86_400_000);
    const owed = `${formatAmount(b.targetMinor, cur)} ${cur}`;
    const have = bal(cur);
    const covered = !!have && have.balanceMinor - have.reservedMinor >= b.targetMinor;
    let body = covered
      ? `Your ${cur} pocket covers it.`
      : `Your ${cur} pocket has ${formatAmount(have?.balanceMinor ?? 0n, cur)} ${cur}.`;
    if (!covered && profile.home !== cur) {
      try {
        const r = await liveMidRate(profile.home, cur);
        const need = sourcePrincipalFor(b.targetMinor - (have?.balanceMinor ?? 0n), parseRate(r.mid, profile.home, cur));
        body += ` Covering the rest from ${profile.home} needs about ${formatAmount(need, profile.home)} ${profile.home} at today's rate.`;
      } catch { /* rate unavailable: say less rather than guess */ }
    }
    out.push({
      id: `bill-${b.id}`,
      severity: days < 0 ? 'urgent' : days <= 14 ? 'urgent' : days <= 30 ? 'attention' : 'info',
      title: days < 0 ? `${b.description} is overdue` : `${b.description}: ${owed} due in ${days} days`,
      body,
      ask: `Pay my ${b.description.toLowerCase()}`,
      askLabel: 'Prepare payment',
    });
  }

  // 2. The rate that matters most to this student, this week.
  try {
    const h = await fxHistory(profile.home, profile.study, 30);
    const wk = Number(h.change7dPercent ?? 0);
    if (Math.abs(wk) >= 0.3) {
      const nextBill = bills.find((b) => b.currency === profile.study);
      let impact = '';
      if (nextBill) {
        const delta = Math.abs((Number(nextBill.targetMinor) / 10 ** 2) * (wk / 100));
        impact = ` On your ${formatAmount(nextBill.targetMinor, nextBill.currency as Currency)} ${nextBill.currency} bill that is roughly ${delta.toFixed(0)} ${profile.study} of difference.`;
      }
      out.push({
        id: 'fx-week',
        severity: wk < 0 ? 'attention' : 'good',
        title: `${profile.home} ${wk < 0 ? 'weakened' : 'strengthened'} ${Math.abs(wk).toFixed(2)}% against ${profile.study} this week`,
        body: `30-day range ${h.low.rate}–${h.high.rate}.${impact} This is history, not a forecast.`,
        ask: `How is the ${profile.home} to ${profile.study} rate doing?`,
        askLabel: 'Explain',
      });
    }
  } catch { /* ECB does not publish every pair */ }

  // 3. Rate alerts: check them now, fire the ones that hit.
  const alerts = await db.select().from(rateAlerts).where(and(eq(rateAlerts.sessionId, session.id), isNull(rateAlerts.firedAt)));
  for (const a of alerts) {
    try {
      const r = await liveMidRate(a.base as Currency, a.quote as Currency);
      const hit = a.direction === 'above' ? Number(r.mid) >= Number(a.threshold) : Number(r.mid) <= Number(a.threshold);
      if (hit) {
        await db.update(rateAlerts).set({ firedAt: new Date() }).where(eq(rateAlerts.id, a.id));
        out.push({
          id: `alert-${a.id}`,
          severity: 'good',
          title: `${a.base}/${a.quote} is ${r.mid} — your alert hit`,
          body: `You asked to know when it went ${a.direction} ${a.threshold}.`,
          ask: `Convert some ${a.base} to ${a.quote}`,
          askLabel: 'Convert',
        });
      }
    } catch { /* skip */ }
  }

  // 4. Things waiting on the student.
  const pending = await listProposals(db, session.id, true);
  if (pending.length) {
    out.push({
      id: 'pending',
      severity: 'attention',
      title: `${pending.length} action${pending.length > 1 ? 's' : ''} waiting for your approval`,
      body: pending.map((p) => p.title).join(' · '),
    });
  }

  if (out.length === 0) {
    out.push({
      id: 'calm',
      severity: 'good',
      title: 'Nothing needs you today',
      body: 'No bills due soon and no rate moves worth acting on. Paste an invoice and I will set up the payment.',
    });
  }
  const order = { urgent: 0, attention: 1, good: 2, info: 3 };
  return out.sort((a, b) => order[a.severity] - order[b.severity]);
}
